# ════════════════════════════════════════════════════════════════════════════
# dsEHP_1 IMMUNE ANALYSIS
# ════════════════════════════════════════════════════════════════════════════
cat('\n══ dsEHP_1 immune signature analysis ══\n')

# ── Analysis 1: dsEHP_1 immune gene expression vs groupmates ────────────

# Use sensitivity DDS (n = 11, includes dsEHP_1)
vsd_sens = varianceStabilizingTransformation(dds_sens, blind = TRUE)
vst_mat  = assay(vsd_sens)

dsEHP_samples = c('dsEHP_1', 'dsEHP_2', 'dsEHP_3')
dsEHP_present = intersect(dsEHP_samples, colnames(vst_mat))

if (length(dsEHP_present) == 3) {
  immune_ids_in_data = intersect(immune_gene_set, rownames(vst_mat))

  # Compute dsEHP_1 expression vs dsEHP_2/3 mean for immune genes
  dsEHP_1_expr  = vst_mat[immune_ids_in_data, 'dsEHP_1']
  dsEHP_23_mean = rowMeans(vst_mat[immune_ids_in_data, c('dsEHP_2', 'dsEHP_3')])
  ehp_mean      = rowMeans(vst_mat[immune_ids_in_data,
                                   grep('^EHP_', colnames(vst_mat))])

  immune_comparison = data.frame(
    gene = immune_ids_in_data,
    dsEHP_1 = dsEHP_1_expr,
    dsEHP_23_mean = dsEHP_23_mean,
    EHP_mean = ehp_mean,
    stringsAsFactors = FALSE
  ) %>%
    mutate(
      diff_vs_groupmates = dsEHP_1 - dsEHP_23_mean,
      diff_vs_EHP = dsEHP_1 - EHP_mean,
      direction_vs_groupmates = ifelse(diff_vs_groupmates > 0, 'up', 'down'),
      closer_to_EHP = abs(dsEHP_1 - EHP_mean) < abs(dsEHP_23_mean - EHP_mean)
    ) %>%
    left_join(
      annotation_df %>% select(gene_id, description),
      by = c('gene' = 'gene_id')
    ) %>%
    arrange(desc(abs(diff_vs_groupmates)))

  n_elevated = sum(immune_comparison$diff_vs_groupmates > 0)
  n_closer_ehp = sum(immune_comparison$closer_to_EHP)
  cat(sprintf('Immune genes in data: %d\n', nrow(immune_comparison)))
  cat(sprintf('Elevated in dsEHP_1 vs groupmates: %d / %d (%.1f%%)\n',
              n_elevated, nrow(immune_comparison),
              100 * n_elevated / nrow(immune_comparison)))
  cat(sprintf('dsEHP_1 closer to EHP group mean than dsEHP_2/3: %d (%.1f%%)\n',
              n_closer_ehp, 100 * n_closer_ehp / nrow(immune_comparison)))

  suppressMessages(write_csv(
    immune_comparison,
    file.path(res_dir, 'dsEHP1_immune_expression_comparison.csv')))

  # Plot: dsEHP_1 vs groupmate mean for immune genes, coloured by
  # whether dsEHP_1 is closer to EHP mean
  p_dsEHP1_immune = ggplot(immune_comparison,
                           aes(x = dsEHP_23_mean, y = dsEHP_1,
                               colour = closer_to_EHP)) +
    geom_abline(slope = 1, intercept = 0, linetype = 'dashed',
                colour = 'grey50') +
    geom_point(alpha = 0.6, size = 1.5) +
    geom_text_repel(
      data = immune_comparison %>%
        filter(abs(diff_vs_groupmates) > 2) %>%
        slice_head(n = 15),
      aes(label = substr(description, 1, 30)),
      size = 2.3, max.overlaps = 15
    ) +
    scale_colour_manual(
      values = c('TRUE' = '#D6604D', 'FALSE' = '#4393C3'),
      labels = c('Closer to dsEHP_2/3', 'Closer to EHP group'),
      name = 'dsEHP_1 profile'
    ) +
    labs(title = 'dsEHP_1 immune gene expression vs dsEHP_2/3 mean',
         subtitle = sprintf('%d / %d immune genes: dsEHP_1 closer to EHP than to groupmates',
                            n_closer_ehp, nrow(immune_comparison)),
         x = 'dsEHP_2/3 mean (VST)', y = 'dsEHP_1 (VST)') +
    theme_bw(base_size = 12)

  ggsave(file.path(res_dir, 'dsEHP1_immune_vs_groupmates.png'),
         p_dsEHP1_immune, width = 9, height = 7, dpi = plot_dpi)
  cat('Saved dsEHP_1 immune comparison plot\n')
}

# ── Analysis 2: Sensitivity GSEA for custom immune set ──────────────────

cat('\nRunning sensitivity GSEA on immune gene set...\n')

# Load sensitivity interaction ranks
sens_int_path = file.path(de_dir,
                          'multifactor_de_sensitivity/tables/DE_interaction.csv')

if (file.exists(sens_int_path)) {
  sens_int_de = read_csv(sens_int_path, show_col_types = FALSE)

  sens_ranked = sens_int_de %>%
    filter(!is.na(stat)) %>%
    select(gene, stat) %>%
    arrange(desc(stat))

  # Run fgsea with custom set (min_size = 3 for the single custom set)
  sens_fgsea = run_fgsea(sens_ranked, custom_sets, min_size = 3)

  cat('\nSensitivity GSEA (interaction with dsEHP_1):\n')
  cat(sprintf('  NES = %.3f, p = %.2e, padj = %.2e\n',
              sens_fgsea$NES[1], sens_fgsea$pval[1], sens_fgsea$padj[1]))

  # Compare with primary
  primary_custom_path = file.path(enr_table_dir,
                                  'gsea_interaction_custom.csv')
  if (file.exists(primary_custom_path)) {
    primary_custom = read_csv(primary_custom_path, show_col_types = FALSE)
    cat(sprintf('\nPrimary GSEA (interaction without dsEHP_1):\n'))
    cat(sprintf('  NES = %.3f, p = %.2e, padj = %.2e\n',
                primary_custom$NES[1], primary_custom$pval[1],
                primary_custom$padj[1]))

    cat(sprintf('\nShift: NES %.3f -> %.3f (delta = %.3f)\n',
                primary_custom$NES[1], sens_fgsea$NES[1],
                sens_fgsea$NES[1] - primary_custom$NES[1]))
  }

  # Enrichment curve for sensitivity interaction
  sens_ranks_vec = setNames(sens_ranked$stat, sens_ranked$gene)
  p_sens_curve = plotEnrichment(immune_gene_set, sens_ranks_vec) +
    labs(title = 'Immune gene set: interaction (with dsEHP_1)',
         subtitle = sprintf('NES = %.2f, p = %.2e',
                            sens_fgsea$NES[1], sens_fgsea$pval[1]),
         x = 'Rank', y = 'Enrichment score') +
    theme_bw(base_size = 12)

  # Side-by-side: primary vs sensitivity immune GSEA curves
  if (exists('curve_plots') && 'interaction' %in% names(curve_plots)) {
    p_primary_curve = curve_plots[['interaction']]

    # Add NES annotation to primary curve
    if (file.exists(primary_custom_path)) {
      p_primary_curve = p_primary_curve +
        labs(subtitle = sprintf('NES = %.2f, p = %.2e',
                                primary_custom$NES[1],
                                primary_custom$pval[1]))
    }

    p_gsea_comparison = (p_primary_curve | p_sens_curve) +
      plot_annotation(
        title = 'Effect of dsEHP_1 on immune gene set enrichment (interaction term)'
      )

    ggsave(file.path(res_dir, 'dsEHP1_immune_gsea_comparison.png'),
           p_gsea_comparison, width = 14, height = 5, dpi = plot_dpi)
    cat('Saved dsEHP_1 GSEA comparison\n')
  }

  # Save summary table
  gsea_summary = tibble(
    analysis = c('Primary (no dsEHP_1)', 'Sensitivity (with dsEHP_1)'),
    NES = c(primary_custom$NES[1], sens_fgsea$NES[1]),
    pval = c(primary_custom$pval[1], sens_fgsea$pval[1]),
    padj = c(primary_custom$padj[1], sens_fgsea$padj[1])
  )
  suppressMessages(write_csv(
    gsea_summary,
    file.path(res_dir, 'dsEHP1_immune_gsea_summary.csv')))

} else {
  cat(sprintf('WARNING: %s not found — cannot run sensitivity GSEA\n',
              sens_int_path))
}


